class MinPriorityQueue {
  constructor(){ this.h = []; }
  insert(el, v){ this.h.push({el, v}); let i = this.h.length-1; while(i>0){ const p = (i-1>>1); if(this.h[i].v < this.h[p].v){ [this.h[i], this.h[p]] = [this.h[p], this.h[i]]; i = p; } else break; } }
  extractMin(){ const r = this.h[0]; this.h[0] = this.h[this.h.length-1]; this.h.pop(); if(this.h.length){ let i=0; while(true){ const l=2*i+1, rr=2*i+2; let s=i; if(l<this.h.length && this.h[l].v<this.h[s].v) s=l; if(rr<this.h.length && this.h[rr].v<this.h[s].v) s=rr; if(s!==i){ [this.h[i],this.h[s]]=[this.h[s],this.h[i]]; i=s; } else break; } } return r.el; }
  isEmpty(){ return this.h.length === 0; }
}
